// WHAT: Fact-check runs — labelled claims generated by ON, marked by the learner,
//       and cards minted from the marks that were wrong.
// WHY: Step 4b of the spec. Verification is the active ingredient, and its rule is
//      explicit: an error you catch (or fail to catch) becomes a flashcard, because
//      caught errors make the strongest cards.
import { createHash } from 'node:crypto';
import { generatedCardId } from './cardidentity.mjs';
import { findTransformation, runTransformation } from './opennotebook.mjs';
import { readCards, readFactChecks, writeCards, writeFactChecks } from './sidecar.mjs';
import { todayISO } from './schedule.mjs';
import { assertPlainObject, optionalString } from './validation.mjs';

export const TRANSFORMATION_NAME = 'fact_check_claims';

/** Generation is slow, so inputs are bounded and the UI says which slice was used. */
export const MAX_INPUT_CHARS = 6000;

/**
 * Parse the transformation's output into labelled claims.
 *
 * Expected shape, one per line:
 *   TRUE | claim
 *   FALSE | claim | correction: ...
 *
 * Deliberately forgiving — a local model may add stray numbering or bullets — but it
 * never guesses a truth value: a line that doesn't clearly start TRUE/FALSE is dropped
 * rather than assumed, and the caller is told how many were unusable.
 */
export function parseClaims(output) {
  const claims = [];
  let skipped = 0;

  for (const raw of String(output ?? '').split('\n')) {
    const line = raw.trim().replace(/^[-*\d.)\s]+/, '');
    if (!line) continue;

    const match = /^(TRUE|FALSE)\s*\|\s*(.+)$/i.exec(line);
    if (!match) {
      skipped += 1;
      continue;
    }

    const truth = match[1].toUpperCase() === 'TRUE';
    const rest = match[2];
    const parts = rest.split('|').map((p) => p.trim());
    const text = parts[0];
    if (!text) {
      skipped += 1;
      continue;
    }

    const correction = parts[1]?.replace(/^correction:\s*/i, '') ?? null;
    claims.push({
      id: `c${claims.length + 1}`,
      text,
      truth,
      // A false claim without a correction is still usable; the truth flag is the
      // part the exercise depends on.
      correction: truth ? null : correction,
    });
  }

  return { claims, skipped };
}

const deckKey = (sourceId, section) => `${sourceId}#${section || 'all'}`;
const sourceHash = (text) => createHash('sha256').update(text).digest('hex');

/** Fields that give away a claim's verdict. Stripped from anything sent before submit. */
const ANSWER_FIELDS = ['truth', 'correction'];

/**
 * A claim record safe to send to the browser: the claims, without their verdicts.
 *
 * This is the fact-check counterpart of `stripAnswers` in lib/grading.mjs, and it exists
 * for the same reason: verification is the active ingredient, so an exercise where the
 * answers arrived with the questions measures nothing. Generation stripped its own
 * response, but `GET /api/factcheck` returned the stored records verbatim — every truth
 * value was one devtools panel away, for every set, before any attempt.
 *
 * Every pre-submit response goes through here. Only the scored `/run` response reveals.
 */
export function stripClaimAnswers(record) {
  return {
    ...record,
    claims: record.claims.map((claim) => {
      const safe = { ...claim };
      for (const field of ANSWER_FIELDS) delete safe[field];
      return safe;
    }),
  };
}

/** The same, for the whole `<source>#<section>` -> record map. */
export function stripAllClaimAnswers(all) {
  return Object.fromEntries(Object.entries(all).map(([key, record]) => [key, stripClaimAnswers(record)]));
}

/** Generate and persist a claim set for one source section. */
export async function generateClaims(topicSlug, { sourceId, sourceTitle, section, text }) {
  const transformation = await findTransformation(TRANSFORMATION_NAME);
  if (!transformation) {
    throw Object.assign(
      new Error(`Open Notebook has no "${TRANSFORMATION_NAME}" transformation. Create it in ON, then retry.`),
      { status: 503 },
    );
  }

  const excerpt = text.slice(0, MAX_INPUT_CHARS);
  const { output, model } = await runTransformation(transformation.id, excerpt);
  const { claims, skipped } = parseClaims(output);

  if (claims.length === 0) {
    // Do not fabricate an exercise out of unparseable output — say what happened.
    throw Object.assign(
      new Error('The model returned no parseable claims. Try regenerating, or pick a longer section.'),
      { status: 502, raw: output.slice(0, 400) },
    );
  }

  const record = {
    source_id: sourceId,
    source_title: sourceTitle,
    section: section || null,
    generated: new Date().toISOString(),
    model,
    truncated: text.length > MAX_INPUT_CHARS,
    input_chars: excerpt.length,
    source_hash: sourceHash(text),
    prompt_version: 'fact-check-claims-v1',
    skipped_lines: skipped,
    claims,
  };

  const all = readFactChecks(topicSlug);
  all[deckKey(sourceId, section)] = record;
  writeFactChecks(topicSlug, all);
  return record;
}

export function getClaims(topicSlug, sourceId, section) {
  return readFactChecks(topicSlug)[deckKey(sourceId, section)] ?? null;
}

/**
 * Score a run and mint cards for the marks that were wrong.
 *
 * "Wrong mark" means the learner's verdict disagreed with the claim's truth — either a
 * false claim they accepted, or a true claim they rejected. Both are misconceptions
 * worth carding, which is why the card records what they thought as well as the truth.
 */
export function proposeRun(record, marks, confidence = {}) {
  const results = record.claims.map((claim) => {
    const marked = marks[claim.id];
    const answered = typeof marked === 'boolean';
    return {
      ...claim,
      marked: answered ? marked : null,
      confidence: confidence[claim.id] ?? null,
      correct: answered ? marked === claim.truth : false,
      answered,
    };
  });

  return { results };
}

/**
 * Final learner adjudications, not model proposals, decide evidence and corrective cards.
 *
 * `accepted` retains the model's proposed truth. `corrected` requires an explicit truth
 * supplied by the learner. `disputed` remains unresolved and cannot become final evidence.
 */
export function adjudicateRun(record, proposed, decisions = {}) {
  const results = proposed.map((proposal) => {
    // `decisions` came from request JSON. Never treat inherited keys as learner input:
    // generated ids are safe today, but the trust boundary belongs here rather than in
    // an assumption about every future claim-id generator.
    const decision = Object.hasOwn(decisions, proposal.id) ? decisions[proposal.id] : null;
    // Adjudication is claim-level and resumable. A later browser interaction normally
    // sends only the decision the learner just made; do not turn every omitted earlier
    // decision back into a model-only proposal. The previous result is durable evidence
    // until the learner expressly replaces it with a new decision.
    if (!decision && ['accepted', 'corrected', 'disputed'].includes(proposal.adjudication)) {
      return { ...proposal };
    }
    if (!decision) {
      return { ...proposal, adjudication: 'pending' };
    }
    assertPlainObject(decision, `decision for ${proposal.id}`, { maxKeys: 4 });
    if (!['accept', 'correct', 'dispute'].includes(decision.action)) {
      return { ...proposal, adjudication: 'pending' };
    }
    const rationale = optionalString(decision.rationale, 'rationale', { max: 2_000 });
    if (decision.action === 'dispute') return { ...proposal, adjudication: 'disputed', rationale };
    if (decision.action === 'correct' && typeof decision.truth !== 'boolean') {
      return { ...proposal, adjudication: 'pending', error: 'a corrected claim needs a true/false verdict' };
    }
    const truth = decision.action === 'correct' ? decision.truth : proposal.truth;
    const correction = decision.action === 'correct'
      ? (optionalString(decision.correction, 'correction', { max: 4_000 }) ?? proposal.correction)
      : proposal.correction;
    const marked = proposal.marked;
    const answered = proposal.answered;
    return {
      ...proposal,
      truth,
      correction,
      correct: answered ? marked === truth : false,
      adjudication: decision.action === 'correct' ? 'corrected' : 'accepted',
      rationale,
    };
  });
  const final = results.filter((result) => result.adjudication === 'accepted' || result.adjudication === 'corrected');
  const wrong = final.filter((result) => !result.correct);
  const disputed = results.filter((result) => result.adjudication === 'disputed');
  const pending = results.filter((result) => result.adjudication === 'pending');
  return {
    results,
    score: final.length - wrong.length,
    max: final.length,
    wrong: wrong.map((result) => result.id),
    disputed: disputed.map((result) => result.id),
    pending: pending.map((result) => result.id),
    complete: pending.length === 0 && disputed.length === 0,
  };
}

/** Mint corrective cards only from fully final, learner-adjudicated results. */
export function cardsFromAdjudication(topicSlug, record, adjudicated) {
  const wrong = adjudicated.results.filter((result) =>
    (result.adjudication === 'accepted' || result.adjudication === 'corrected') && !result.correct,
  );

  const cards = readCards(topicSlug);
  const existing = new Set(cards.map((c) => c.source_ref).filter(Boolean));
  const created = [];

  for (const result of wrong) {
    const ref = `factcheck:${record.source_id}#${record.section || 'all'}:${result.id}`;
    if (existing.has(ref)) continue;

    const verdict = result.truth ? 'TRUE' : 'FALSE';
    const back = [
      `This claim is ${verdict}.`,
      result.correction ? `Correction: ${result.correction}` : null,
      result.answered
        ? `You marked it ${result.marked ? 'true' : 'false'}.`
        : 'You left it unmarked.',
    ].filter(Boolean).join('\n\n');

    const card = {
      id: generatedCardId('factcheck', ref),
      front: `True or false? ${result.text}`,
      back,
      concept_slug: record.concept_slug ?? null,
      source: 'factcheck',
      source_ref: ref,
      created: todayISO(),
    };
    cards.push(card);
    existing.add(ref);
    created.push(card);
  }

  if (created.length > 0) writeCards(topicSlug, cards);

  return created;
}
